//! Lower IR to asm6502 assembly text.
//!
//! Each BASIC line gets its own label `Lnnnnn`, so GOTO/GOSUB jumps
//! between lines without us doing any address fixup — the assembler
//! resolves it via two-pass label resolution.
//!
//! Numeric values flow through BASIC's FAC1 (Floating Accumulator).
//! Expressions evaluate post-order: for `lhs OP rhs` we evaluate `rhs`
//! first into FAC, push the result to a stack-allocated temp slot, then
//! evaluate `lhs` into FAC and apply the binary op with the temp as
//! memory operand. This works uniformly for `+ - * /` because BASIC's
//! FADD/FSUB/FMULT/FDIV all compute `FAC = FAC OP mem[A,Y]` — the
//! operand is the second one, which is exactly what we stored.
//!
//! Comparison ops produce -1.0 (true) / 0.0 (false) per BASIC v2 by
//! routing FCOMP's signum through GIVAYF.
//!
//! FOR/NEXT: each FOR pushes a frame on a compile-time stack and
//! allocates a per-loop slot for END (the loop bound). The STEP value
//! is required to be a literal at lower-time so its sign — which decides
//! the loop-exit comparison direction — is known statically; it's
//! interned in the float constant pool like any other literal.

use std::collections::{HashMap, HashSet};
use std::fmt::Write as _;

use crate::ast::{
    self, BinOp, DataValue, FnName, Func1, OnBranchKind, ScreenRectOp, ScreenScrollOp, VarKind,
    VarName,
};
use crate::ir::{
    self, ArrayInduction, ArrayInductionIndex, Expr, MemTransferOp, PrintPiece, ReadTarget, Stmt,
    StrExpr, ThenIr,
};
use crate::runtime as rt;

/// Where the machine code lives in memory after the SYS stub. Keep in
/// sync with `pack.rs`. Used when `CompileOptions::custom_start_address`
/// is `None`; otherwise the user-supplied address takes over and the
/// SYS launcher is omitted from the packed .prg.
pub const CODE_ORIGIN: u16 = 0x080D;

#[derive(Debug)]
pub enum CodegenError {
    Unsupported(&'static str),
    UnmatchedNext {
        line: u16,
    },
    UnopenedFor {
        line: u16,
    },
    UnmatchedUntil {
        line: u16,
    },
    UnmatchedEndLoop {
        line: u16,
    },
    ExitWithoutLoop {
        line: u16,
    },
    DoneWithoutDo {
        line: u16,
    },
    ElseWithoutDo {
        line: u16,
    },
    /// Reserved error for `NEXT name` that names a different variable
    /// than the matching `FOR`. The current frontend rewrites all
    /// `NEXT` lists into anonymous closes, so this never fires; kept
    /// to preserve the wire-format of the error enum for tooling.
    #[allow(dead_code)]
    NextVarMismatch {
        line: u16,
        expected: String,
        got: String,
    },
    StringInNumericContext,
    UndimensionedArray(String),
    DuplicateDim(String),
    ArrayDimMismatch {
        name: String,
        expected: usize,
        got: usize,
    },
    UndefinedFn(String),
    DuplicateDefFn(String),
}

impl std::fmt::Display for CodegenError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            CodegenError::Unsupported(w) => write!(f, "{w} not yet supported"),
            CodegenError::UnmatchedNext { line } => write!(f, "line {line}: NEXT without FOR"),
            CodegenError::UnopenedFor { line } => {
                write!(f, "line {line}: FOR not closed by NEXT")
            }
            CodegenError::UnmatchedUntil { line } => write!(f, "line {line}: UNTIL without REPEAT"),
            CodegenError::UnmatchedEndLoop { line } => {
                write!(f, "line {line}: END LOOP without LOOP")
            }
            CodegenError::ExitWithoutLoop { line } => write!(f, "line {line}: EXIT without loop"),
            CodegenError::DoneWithoutDo { line } => write!(f, "line {line}: DONE without DO"),
            CodegenError::ElseWithoutDo { line } => write!(f, "line {line}: ELSE without DO"),
            CodegenError::NextVarMismatch {
                line,
                expected,
                got,
            } => write!(
                f,
                "line {line}: NEXT {got} doesn't match innermost FOR {expected}"
            ),
            CodegenError::StringInNumericContext => {
                write!(f, "string value used where number was expected")
            }
            CodegenError::UndimensionedArray(name) => {
                write!(f, "array {name} used without DIM")
            }
            CodegenError::DuplicateDim(name) => {
                write!(f, "array {name} declared with DIM more than once")
            }
            CodegenError::ArrayDimMismatch {
                name,
                expected,
                got,
            } => write!(
                f,
                "array {name}: declared with {expected} dimension(s), used with {got}",
            ),
            CodegenError::UndefinedFn(name) => {
                write!(f, "FN {name} called without a matching DEF FN")
            }
            CodegenError::DuplicateDefFn(name) => {
                write!(f, "DEF FN {name} declared more than once")
            }
        }
    }
}

impl std::error::Error for CodegenError {}

pub fn emit_with_profile(module: &ir::Module, profile: Profile) -> Result<String, CodegenError> {
    emit_with_profile_at(module, profile, CODE_ORIGIN)
}

/// Same as [`emit_with_profile`] but the caller picks the origin. Used
/// by the `custom_start_address` path to relocate code away from $080D.
pub fn emit_with_profile_at(
    module: &ir::Module,
    profile: Profile,
    origin: u16,
) -> Result<String, CodegenError> {
    let analysis = CodegenAnalysis::from_module(module);
    let mut cg = Codegen::new(profile, analysis);
    cg.code_origin = origin;
    cg.run(module)?;
    cg.finish()
}

// ===== Codegen state =====

struct Codegen {
    code: String,
    next_id: usize,
    strings: Vec<(String, Vec<u8>)>,
    /// f64 bit-pattern → label, for dedup of float constants.
    floats_index: HashMap<u64, String>,
    floats_order: Vec<(String, [u8; 5])>,
    vars_index: HashMap<VarName, String>,
    /// (label, byte-size). String vars are 2-byte pointer slots; floats
    /// are 5-byte MFLPT.
    vars_order: Vec<(String, usize)>,
    /// Per-slot in-use bitmap for the integer-island temp pool. Slot
    /// `i` holds 2 bytes at label `T<i>`. Tracked as a `Vec<bool>`
    /// (free-list) so out-of-order frees work correctly — the prior
    /// counter design assumed strict LIFO and aliased `T1` when a
    /// caller held it across a sub-evaluation that allocated and
    /// released its own temps. Caught by edge140
    /// (`t% + a%(i) + a%(i+5)` produced `2 * a%(i+5)` because the
    /// inner `i+5` evaluation alloc'd into the same `T1` slot the
    /// outer `t% + a%(i)` was still using as its result).
    temp_used: Vec<bool>,
    temp_max: usize,
    for_stack: Vec<ForFrame>,
    /// Most recently popped FOR frame, kept around so a stray NEXT
    /// (e.g. v2 idiom of multiple NEXTs sharing one FOR via
    /// `IF cond THEN ... NEXT : GOTO` plus a sibling outer NEXT) can
    /// re-emit loop continuation code rather than hitting an
    /// `UnmatchedNext` compile error.
    last_popped_for: Option<ForFrame>,
    structured_loop_stack: Vec<StructuredLoopFrame>,
    do_stack: Vec<DoFrame>,
    /// Number of per-FOR END slots allocated so far. We never free them
    /// (not worth the bookkeeping for a few bytes).
    for_end_slots: usize,
    /// Number of dynamic-STEP sign slots allocated (1 byte each, named
    /// `FS_SIGN_<n>`). NEXT reads the matching one to decide which way
    /// the exit-sign branch should go when STEP wasn't a constant at
    /// compile time.
    for_step_sign_slots: usize,
    /// Number of int-FOR counter slots allocated. Each is 2 bytes,
    /// emitted at the end of the binary as `FI_<n>`.
    for_int_slots: usize,
    /// Number of u8-FOR counter slots allocated. Each is 1 byte,
    /// emitted at the end of the binary as `FU_<n>`. Used when
    /// start/end fit `[0,255]` and the literal step exactly reaches
    /// the end value without wrapping.
    for_u8_slots: usize,
    /// 5-byte float slots holding the running `var * K` value for
    /// FORs whose body matches the loop-induction pattern. Emitted
    /// at the end of the binary as `FB_<n>`.
    for_induction_slots: usize,
    /// 2-byte ZP-pointer slots holding `&A[loop_var]` for FORs whose
    /// body matches the array-pointer-induction pattern. Emitted at
    /// the end of the binary as `AP_<n>`. Allocated through the
    /// shared ZP pool when there's room; otherwise BSS-resident.
    for_array_ptr_slots: usize,
    /// True iff at least one int-FOR loop was emitted — pulls in the
    /// 2-byte `__FOR_DIFF_LO`/`__FOR_DIFF_HI` shared scratch used by
    /// the signed-16-bit compare at NEXT.
    used_int_for: bool,
    /// Track whether we ever needed BOOL_TO_FAC, so we only emit the
    /// helper when something refers to it.
    used_bool_to_fac: bool,
    /// Track whether any GET was emitted, so the shared `__GET_NUM`
    /// helper subroutine is only included when needed.
    used_get_num: bool,
    /// Track whether anything ever needs to print a length-prefixed
    /// string (literals or string variables).
    used_str_print: bool,
    /// Track whether the int16-print fast path was used in any PRINT.
    /// Emits the shared `__PRINT_INT16` helper that absorbs
    /// GIVAYF + __PRINT_FAC into one JSR.
    used_print_int16: bool,
    /// Track whether `GET A$` is used; emits a 1-char heap slot that
    /// holds the latest keystroke and a small helper to fill it.
    used_get_str: bool,
    /// True iff a GET-like path needs the shared 2-byte `__GET_HEAP`
    /// buffer. `used_get_str` additionally emits the non-blocking
    /// helper; blocking KEYGET string sites fill the buffer inline.
    used_get_heap: bool,
    /// True iff any `ON KEY ... GOTO/GOSUB` appeared. Pulls in the
    /// `__ON_KEY_CHECK` poll helper, the `__ON_KEY_*` BSS slots,
    /// and inserts a `JSR __ON_KEY_CHECK` after every line-number
    /// stamp so a registered key fires before the next user
    /// statement runs.
    used_on_key: bool,
    /// `ON ERROR` / `RESUME` / `ERROR n` appears anywhere in the
    /// program. Gates the per-line `__TSB_RESUME_NEXT` stamp, the
    /// `__TSB_ERROR` dispatcher, and the `__TSB_GOTO_LINE` table.
    used_on_error: bool,
    /// True when the program writes to `ER` or `EL`, i.e. the user
    /// is using them as ordinary BASIC v2 variable names rather
    /// than the error pseudo-vars. When set, both reads
    /// and writes route through a regular Float scalar slot.
    er_el_as_user_var: bool,
    /// `RESUME` (Same/Next) needs the runtime line-table walker.
    used_tsb_goto_line: bool,
    /// True iff any `SQR(...)` was emitted. Pulls in the
    /// `__FAST_SQRT` helper (Newton-Raphson, ~80 bytes) and the
    /// 5+5-byte `__SQRT_N`/`__SQRT_Y` slots used as scratch by
    /// the iteration. Custom helper beats ROM `$BF71` (which
    /// computes `EXP(0.5*LOG(x))`) by ~2x on per-call cycles.
    used_fast_sqrt: bool,
    /// Track whether `CHR$(...)` was used in any PRINT/LET-string
    /// context, to emit the shared `__CHR_HEAP` slot.
    used_chr_heap: bool,
    /// True iff CHR$ landed in any string-expression context — emits
    /// the `__CHR_NEW` helper that allocates a fresh temp chunk
    /// from the string heap per call. (Replaces the static buffer
    /// to avoid CHR$(A)+CHR$(B) collisions.)
    used_chr_new: bool,
    /// Track whether `+` was used between strings; emits the heap +
    /// __STR_CONCAT helper.
    used_concat: bool,
    used_str_from_number: bool,
    used_str_left: bool,
    used_str_right: bool,
    used_str_mid: bool,
    /// True iff anything in the program needs the heap initialised at
    /// startup (any of: concat, STR$, LEFT$, RIGHT$, MID$).
    heap_init_needed: bool,
    /// True iff `VAL` was used; emits the shared __VAL_HELPER routine.
    used_val: bool,
    /// True iff `NRM(s$)` was used as a function (distinct
    /// from the NRM statement). Emits `__NRM_HELPER` which parses
    /// the string with format auto-detection (hex if len < 8,
    /// binary if len ≥ 8, optional `$`/`%` prefix tolerated).
    used_nrm_helper: bool,
    /// True iff `USR` was used; emits the USR vector wrapper and makes
    /// startup initialise the BASIC-compatible vector to a safe RTS.
    used_usr: bool,
    /// True iff `A$(I) = ...` was emitted; pulls in the temporary
    /// pointer slot used to bridge value-eval and address-eval.
    used_array_let_str: bool,
    /// True iff a `Stmt::PokeFill` was emitted — pulls in the
    /// `__POKE_FILL` runtime helper plus its 4-byte pointer/count
    /// scratch (`__PFL_PTR`, `__PFL_CNT`, `__PFL_END`).
    used_poke_fill: bool,
    /// True iff any `INPUT` appears — emits the shared input buffer
    /// and `__INPUT_LINE` helper.
    used_input: bool,
    /// True iff any `INPUT` reads a string variable — pulls in the
    /// `__INPUT_COPY_TO_HEAP` helper alongside the buffer.
    used_input_str: bool,
    /// All DATA values across the whole program, in source order. Empty
    /// when the program has no DATA at all (skips data-block emission
    /// and pointer-init prelude entirely).
    data_values: Vec<ast::DataValue>,
    /// Per-line DATA-pool offsets. Filled by `collect_data` for
    /// every line that contributes DATA values; consumed when
    /// emitting the pool to drop a `__DATA_LINE_<n>:` label so
    /// `RESET <line>` can point the DATA pointer there.
    data_line_offsets: Vec<(u16, usize)>,
    /// Each unique STATIC array variable and its declared dimensions.
    /// Used to allocate `__ARR_<name>` slots at the end of the binary
    /// and to validate that index counts match. `DIM A(10)` records
    /// `[10]`, `DIM A(10, 5)` records `[10, 5]`. Arrays whose DIM
    /// expressions don't fold to literals go to `runtime_arrays`.
    arrays: HashMap<VarName, Vec<u16>>,
    /// Insertion order so array-block emission is deterministic.
    arrays_order: Vec<VarName>,
    /// Arrays whose DIM expressions aren't literal at compile time —
    /// the dim sizes get evaluated and stored in per-array descriptor
    /// slots when the program reaches the DIM statement, and a chunk
    /// is bump-allocated from the runtime array region (which grows
    /// downward from MEMSIZ). The descriptor holds the base pointer
    /// and per-dim max-index; access goes through them.
    runtime_arrays: HashMap<VarName, Vec<Expr>>,
    /// Stable iteration order for runtime arrays.
    runtime_arrays_order: Vec<VarName>,
    /// True iff any runtime DIM was emitted. Pulls in the
    /// `__ARR_HEAP_TOP` allocator slot, the `__DIM_ALLOC` helper, and
    /// changes the string-heap GC margin check to use the array-heap
    /// floor instead of MEMSIZ.
    used_runtime_dim: bool,
    /// True iff any 2-D array reference was emitted; pulls in the
    /// `__MD_TMP_I` and `__MD_TMP_J` 5-byte FAC-stash slots used while
    /// computing the linear element index.
    used_md_array: bool,
    /// True iff any `SPC(...)` (or `TAB(...)`, since TAB tail-calls SPC)
    /// was emitted — pulls in the shared `__SPC` helper.
    used_spc: bool,
    /// True iff any `TAB(...)` was emitted — pulls in `__TAB` on top of
    /// `__SPC`.
    used_tab: bool,
    /// True iff any `PRINT TAB(<expr>)` site emits `JSR __TAB_FAC` —
    /// pulls in the combined FAC_BYTE+TAX+TAB helper.
    used_tab_fac: bool,
    /// True iff any `PRINT SPC(<expr>)` site emits `JSR __SPC_FAC`.
    used_spc_fac: bool,
    /// Each DEF FN in source order, with the parameter slot it writes
    /// to and the body to evaluate. Pre-pass-collected so call sites
    /// can validate FN names statically and so bodies can be emitted as
    /// helper subroutines after the main code.
    def_fns: HashMap<FnName, DefFnInfo>,
    def_fns_order: Vec<FnName>,
    /// True iff any array reference emitted a bounds check. Pulls in
    /// the shared `__BAD_SUBSCRIPT` trap helper and its message string.
    used_bad_subscript: bool,
    /// True iff `emit_bounds_check` (the shared 7-byte JSR variant)
    /// fired anywhere. Pulls in the `__BNDS_CHECK` helper.
    used_bnds_check: bool,
    /// True iff any code path reads a Float array element via the
    /// 3-instruction `LDA $FD; LDY $FE; JSR MOVFM` pattern. Pulls in
    /// the `__LD_ARR` stub so each call site shrinks to a 3-byte JSR.
    used_ld_arr: bool,
    /// Same for stores: `LDX $FD; LDY $FE; JSR MOVMF` becomes
    /// `JSR __ST_ARR`.
    used_st_arr: bool,
    /// True iff the FAC-stash-to-T0 stub fired anywhere. T0 is the
    /// outermost temp slot in `emit_binop`/`emit_compare` and so is
    /// hit by every non-trivial binary op — stubbing it shrinks each
    /// call from 7 bytes to 3.
    used_st_t0: bool,
    /// Same idea for the four float-arithmetic ops with T0 as memory
    /// operand. Each used_op_t0 flag pulls in its own stub.
    used_fadd_t0: bool,
    used_fsub_t0: bool,
    used_fmult_t0: bool,
    used_fdiv_t0: bool,
    /// Float-var load/store usage counts (separate buckets so we can
    /// emit one stub only when it actually beats the inline 7-byte
    /// LDA/LDY/JSR sequence). Filled by `count_var_helpers` before
    /// codegen runs.
    float_var_loads: HashMap<VarName, u32>,
    float_var_stores: HashMap<VarName, u32>,
    /// Same shape but for `%`-typed scalars: how many times the int
    /// var is read into FAC (via GIVAYF). Drives a per-var int-load
    /// stub so promoted vars don't pay an inline 9-byte sequence
    /// at every read site.
    int_var_loads: HashMap<VarName, u32>,
    /// Loop-weighted access counts for `%`-typed scalars, used only to
    /// rank zero-page promotion candidates: a read on a loop-hot line
    /// counts `ZP_LOOP_WEIGHT`×, so hot inner-loop variables win the
    /// scarce pool over cold ones even with fewer source reference
    /// sites. Distinct from `int_var_loads` (which drives stub
    /// emission, where loop-weighting would be counterproductive).
    int_var_zp_hotness: HashMap<VarName, u32>,
    /// Per-(var, op) usage counts for binops where a Var becomes the
    /// memory operand of FADD/FSUB/FMULT/FDIV — bypassing the
    /// ST_T0/LD/FADD_T0 dance entirely. Filled alongside the load/
    /// store counts. Op key is one of Add/Sub/Mul/Div.
    float_var_op_uses: HashMap<(VarName, BinOp), u32>,
    /// Per-dim BNDS_CHECK stub uses. Each unique dim value referenced
    /// by an array bounds check gets its own `__BNDS_<dim>` stub at
    /// the end of the binary; the call site is a 3-byte JSR. Filled
    /// during emission, drained at finish().
    bnds_stub_uses: HashMap<u16, u32>,
    /// Per-(dim_label) stub usage for runtime-dimensioned arrays.
    /// `__BNDS_RT_<dim_label>` does the sign check + 16-bit compare
    /// against the dim slot, trapping to `__BAD_SUBSCRIPT` when the
    /// index is out of range. Each call site is a 3-byte JSR.
    bnds_rt_stub_uses: HashMap<String, u32>,
    /// True iff any string compare was emitted; pulls in the shared
    /// `__STRCMP` helper that walks the pointer pair in
    /// STR_OP_LHS/RHS and returns a signum byte in .A.
    used_strcmp: bool,
    /// True iff any int-array element store fires; pulls in the
    /// shared `__ST_ARR_INT` helper that does
    /// `JSR __FAC_TO_INT16; <store 2 bytes via ARRAY_ADDR>`.
    used_st_arr_int: bool,
    /// Same idea but for numeric-literal mem operands (`X + 1`,
    /// `Y * 2`). Key is the f64's bit pattern so different `1.0`
    /// occurrences merge. The literal goes in the float pool the
    /// usual way; the stub label derives from the pool label.
    float_const_op_uses: HashMap<(u64, BinOp), u32>,
    /// True iff any AND/OR was emitted — pulls in the 2-byte
    /// `__LOGIC_LO`/`__LOGIC_HI` scratch used to stash one operand's
    /// integer truncation across the second operand's evaluation.
    used_logic: bool,
    /// True iff any AND/OR/NOT codegen needs the signed FAC→int16
    /// helper — `FACWORD` itself is unsigned and raises ?ILLEGAL
    /// QUANTITY for negative values (which include BASIC's `-1` truth
    /// constant), so the helper clears the sign, does FACWORD on the
    /// magnitude, then negates the result if the original was negative.
    used_fac_to_int16: bool,
    /// Track whether the non-trapping FAC → i16 helper was used.
    /// Pre-checks the FAC exponent so values that would trip
    /// FACWORD's overflow trap stash 0 in LINNUM instead. Used by
    /// shadow-int sync at INPUT sites where the user's value isn't
    /// statically bounded — moving an existing trap from
    /// "next AND/POKE/CHR$ read" to "INPUT itself" would change
    /// program semantics, so we suppress the trap here and let the
    /// out-of-range value flow through with garbage in the high
    /// byte. Byte-context reads only consult the low byte; other
    /// reads hit the FAC fall-back and re-trap there.
    used_fac_to_int16_notrap: bool,
    /// True iff the int-island MUL helper `__MUL16` was emitted —
    /// pulls in the ~35-byte unsigned 16x16→16 multiplication
    /// routine. Used by `try_emit_int16_eval_addsub` for general
    /// `Mul` nodes that aren't power-of-two.
    used_mul16: bool,
    /// True iff the signed int-island DIV helper `__DIV16` was
    /// emitted. Implements floor-division on signed i16 with a
    /// `?DIVISION BY ZERO` trap. Both DIV(a,b) and MOD(a,b) on
    /// int-island leaf operands route through this single helper —
    /// after the call, NUM ($14/$15) holds the floor quotient and
    /// `__DIV16_REM` holds the floor remainder (sign of divisor).
    used_div16: bool,
    /// True iff the small-constant MUL strength-reduction lowered a
    /// `Var * K` (K ∈ {3, 5, 6, 7, 9, 10, 12, ...}) into a shift+add
    /// chain — pulls in the 2-byte BSS scratch `__SMUL_TMP` used to
    /// stash the pre-shift value when the plan needs to add or
    /// subtract `var` back after shifting.
    used_smul_tmp: bool,
    /// True iff `TI` (the system jiffy counter) was read anywhere —
    /// pulls in the `__READ_TI` helper plus the byte slots and FAC
    /// stash it needs.
    used_read_ti: bool,
    /// True iff `TI$` was read anywhere — pulls in the
    /// `__READ_TI_STR` helper, the binary divide-by-60 routine,
    /// the divide-by-10 routine, plus the 7-byte `__TI_HEAP` slot.
    used_read_ti_str: bool,
    /// True iff a STOP statement was emitted — pulls in the small
    /// helper that prints "BREAK IN <line>" via STROUT + GIVAYF + FOUT
    /// and warm-restarts.
    used_stop: bool,
    /// Last array address computed and currently held in
    /// ARRAY_ADDR_LO/HI ($FD/$FE). When a subsequent array reference
    /// requests the same name + indices, we skip the recomputation.
    /// Cleared at every statement boundary and at any operation known
    /// to clobber $FD/$FE (string-print, LEN, ASC, concat helpers).
    last_array_addr: Option<(VarName, Vec<Expr>)>,
    /// Expressions whose value is definitely still resident in FAC1.
    /// This is a tiny local CSE/liveness cache: helpers that consume or
    /// overwrite FAC clear it, while MOVMF-style stores can add aliases
    /// such as `LET A = expr` -> FAC contains both `expr` and `A`.
    fac_cache: Vec<Expr>,
    /// Runtime-DIM arrays whose `__ARR_<X>_BASE` pointer has already
    /// been guarded against the BSS-zero "DIM not yet run" trap on
    /// every path that can reach the current statement. Each access
    /// emits the OR-test + trap once per epoch and adds the var; later
    /// accesses skip the guard. Cleared at branch-target lines (other
    /// paths may have skipped the DIM), at \`CLR\` / \`RUN\` (those
    /// reset \`__ARR_<X>_BASE\` to zero), and on entry into IF/THEN
    /// bodies whose statements run conditionally.
    runtime_array_base_validated: HashSet<VarName>,
    /// Runtime-DIM arrays whose `__ARR_<X>_BASE` lives in zero-page —
    /// the EQU directive at the top of the binary points the label
    /// at a 2-byte ZP slot, so the per-access \`ADC __ARR_<X>_BASE\`
    /// uses zp addressing automatically (1 byte shorter, 1 cycle
    /// faster) and the BSS slot in \`__VARS_START..__VARS_END\` is
    /// skipped. The set is also our gate for whether to skip BSS
    /// emission for that array's base.
    runtime_array_base_zp: HashSet<VarName>,
    /// True iff any OPEN was emitted — pulls in three byte slots
    /// `__OPEN_F/D/S` used to stage SETLFS arguments across the
    /// per-arg evaluations.
    used_open: bool,
    /// True iff any INPUT# was emitted — pulls in the CHRIN-based
    /// `__INPUT_LINE_FILE` helper alongside the existing INPUT_BUF
    /// machinery.
    used_input_file: bool,
    /// True iff `LET TI$ = ...` was emitted — pulls in the helper that
    /// parses the HHMMSS source string and stamps the jiffy counter.
    used_set_ti: bool,
    /// True iff `PRINT A, B`-style comma was emitted — pulls in the
    /// `__PRINT_COMMA` helper that pads to BASIC v2's 10-column zones.
    used_print_comma: bool,
    /// True iff multi-var INPUT was emitted — pulls in `__EXTRACT_FIELD`
    /// (comma-aware field cutter) and the `__INPUT_POS` cursor + the
    /// 80-byte `__FIELD_BUF` length-prefixed scratch.
    used_input_field: bool,
    /// True iff anything emitted a "must fit in a byte" check — pulls
    /// in the shared `__CHK_BYTE` helper that traps to ?ILLEGAL QUANTITY
    /// when LINNUM_HI is non-zero (i.e., the value just FACWORDed is
    /// >= 256). Used by CHR$, PRINT CHR$, POKE value, WAIT mask/eor.
    used_chk_byte: bool,
    /// True iff the combined `__FAC_BYTE` helper is referenced — does
    /// `FACWORD; CHK_BYTE; LDA LINNUM_LO` (returns the byte in .A).
    /// Replaces the 8-byte triplet at every POKE-value, CharOut, SPC,
    /// TAB, CHR$, etc. site with a 3-byte JSR.
    used_fac_byte: bool,
    /// True iff the no-check FAC-to-byte helper `__FAC_BYTE_OK` is
    /// referenced — used at sites where range facts prove the value
    /// is already in `0..=255`, so the high-byte error check inside
    /// `__FAC_BYTE` would be dead code. Body is just `FACWORD; LDA
    /// LINNUM_LO; RTS` (6 bytes vs ~12 for `__FAC_BYTE`). Distinct
    /// helper rather than inline so the call site stays a 3-byte
    /// JSR — keeps peephole factoring (PH113/PH301) alive on the
    /// surrounding load+convert pair.
    used_fac_byte_ok: bool,
    /// True iff `JOY(n)` was emitted; pulls in the active-low
    /// joystick normaliser helper and its lookup table.
    used_joy: bool,
    /// True iff `PAUSE n` was emitted; pulls in a one-byte jiffy
    /// latch used by the delay loop.
    used_pause: bool,
    /// True iff `PAUSE msg$, n` (the optional leading message form)
    /// was emitted — pulls in the `__PAUSE_MSG_LEN` data byte.
    used_pause_msg: bool,
    /// True iff a screen rectangle helper (FCHR/FCOL/FILL/INV)
    /// was referenced. Pulls in shared rectangle scratch slots.
    used_tsb_rect: bool,
    used_tsb_rect_fill: bool,
    used_tsb_rect_inv: bool,
    used_tsb_rect_move: bool,
    used_tsb_rect_scroll: bool,
    /// True iff `HIRES` was emitted — pulls in the bitmap clear /
    /// mode-set helper plus the default colour-pair pattern.
    used_hires: bool,
    /// True iff a single-pixel hires plot was emitted. Pulls in
    /// `__DRAW`, the per-row bitmap-base lookup table, and the
    /// bit-mask LUT.
    used_hires_draw: bool,
    /// True iff `LINE x1,y1,x2,y2` was emitted — pulls in the
    /// Bresenham helper which depends on `__DRAW`.
    used_hires_line: bool,
    /// True iff `REC x,y,w,h` was emitted — pulls in `__REC` which
    /// chains four `__LINE` calls for the rectangle outline.
    used_hires_rec: bool,
    /// True iff `BLOCK x1,y1,x2,y2` was emitted — pulls in
    /// `__BLOCK` which fills the rectangle with horizontal
    /// `__LINE` calls.
    used_hires_block: bool,
    used_hires_circle: bool,
    used_hires_circle_arc: bool,
    used_hires_mod: bool,
    used_hires_dup: bool,
    used_hires_char: bool,
    used_hires_text: bool,
    used_hires_cursor: bool,
    used_hires_rot: bool,
    used_hires_draw_str: bool,
    used_hires_paint: bool,
    used_hires_angl: bool,
    used_tsb_tmp: bool,
    used_tsb_sid: bool,
    used_music_play: bool,
    used_flash: bool,
    used_bflash: bool,
    /// Gate for the `__INT_TO_HEX` helper that backs `$$<expr>`.
    used_int_to_hex: bool,
    /// Gate for the `__INT_TO_BIN` helper that backs `%%<expr>`.
    used_int_to_bin: bool,
    /// True iff FLASH or BFLASH is used anywhere — gates the
    /// `__TSB_IRQ_INSTALL` prelude call and the `__TSB_IRQ_HANDLER`
    /// definition. The handler bumps `$C516` (zaeirq) every IRQ
    /// (~60 Hz) and toggles `$C5C7` bit 7 every FLASH tick. Programs
    /// use these addresses as polling targets; without
    /// them, `WAIT $C5C7,...` and `UNTIL PEEK($C516)>30` loops
    /// hang forever.
    used_tsb_irq: bool,
    used_fetch: bool,
    used_key_table: bool,
    used_mem_copy: bool,
    used_mem_fill: bool,
    used_scr_snapshot: bool,
    /// True iff sprite register helpers/scratch are needed for MMOB,
    /// MOB SET, RLOCMOB, or CHECK's bit-mask table.
    used_tsb_sprite: bool,
    /// True iff LOW COL / HI COL state slots are referenced.
    used_tsb_lowcol: bool,
    /// True iff `MULTI ON` appears anywhere in the program — gates
    /// the runtime MULTI flag and the `__DRAW_MC` 2-bit pixel path.
    used_tsb_multi: bool,
    /// True iff bare `MEM` appears anywhere — gates emission of
    /// the `__MEM_INIT` helper (chars-to-$E000 copy + VIC bank /
    /// $D018 / KERNAL $0288 reconfigure) and switches CSET 0/1
    /// to the MEM-mode XOR'd $D018 values.
    used_mem_mode: bool,
    /// True iff any drawing command takes (or could take) a mode
    /// argument. CHAR/TEXT always set this since they expose mode;
    /// other commands set it when the parser captured a trailing
    /// mode arg. Gates the per-op dispatch in __DRAW / __DRAW_MC
    /// so simple HIRES programs keep the lean set-only path.
    used_draw_mode: bool,
    /// True iff DETECT/CHECK state is used.
    used_tsb_detect: bool,
    /// string helpers.
    used_str_dup: bool,
    used_str_insert: bool,
    used_inst: bool,
    /// `INSERT box$, …` with a non-literal box pattern — emits the
    /// `__INSERT_BOX_PARSE` helper + `__INSERT_BOX_BUF`/`__INSERT_BOX_TMP`.
    used_insert_box_runtime: bool,
    /// `USE "…###…", v` formatted-PRINT field — emits the
    /// `__USE_FIELD` helper + `__USE_FIELD_WIDTH` ZP/data slots.
    used_use_field: bool,
    /// `MOB SET …,speed` writes or `MMOB`/`RLOCMOB` glide reads —
    /// emits `__MOB_SPEED` (8-byte per-sprite delay table) and the
    /// `__MMOB_GLIDE` helper.
    used_mmob_glide: bool,
    /// String variables that may be involved in pointer-style source
    /// expressions (`A$ = B$`, `A$ = N$(I)`, `N$(I) = B$`). The current
    /// owner-backed LET path copies values, but this set still keeps
    /// the BSS-buffer string optimization conservative around statement
    /// forms that can observe or mutate the same string slot.
    shared_strings: HashSet<VarName>,
    /// String vars whose maximum length is small and statically known,
    /// not aliased, and never written by INPUT/GET/READ. We give each
    /// one a dedicated BSS buffer; LET copies into the buffer and the
    /// var pointer (initialised once at startup) always points at it,
    /// so multi-var loops don't accumulate orphaned heap chunks.
    /// Map value is the maximum payload length (1..=255).
    bss_str_vars: HashMap<VarName, u8>,
    /// True iff any LetStr emitted the BSS-buffer path — pulls in the
    /// `__SBUF_COPY` helper plus its scratch slots.
    used_sbuf_copy: bool,
    /// True iff persistent string assignment copies into an
    /// owner-backed heap chunk. Pulls in `__STR_ASSIGN_OWNED`.
    used_str_assign_owned: bool,
    /// True iff any string LET emits LASTVAR-rewind machinery. Pulls
    /// in the 4 BSS bytes that track the most-recently-stored string
    /// var (`__LAST_STR_VAR_LO/HI` + `__LAST_STR_PTR_LO/HI`) and the
    /// init that zeros them at startup. When the LET's dest is the
    /// same var as the previous string write, rewind
    /// `__HEAP_PTR` to that var's chunk start, so the new
    /// allocation overwrites the now-stale chunk instead of leaving
    /// it as heap garbage.
    used_lastvar_str: bool,
    /// True iff anything triggers garbage collection (FRE call, or an
    /// owner-backed string assignment). Pulls in `__GC_RUN`, a compact
    /// linear collector that follows each chunk's owner back-pointer
    /// instead of scanning every possible BASIC string slot.
    used_gc: bool,
    /// True iff the program contains a `RUN` statement. Pulls in the
    /// `__RUN_RESTART` helper which resets variables, arrays, heap
    /// and DATA pointer back to startup state and jumps to the first
    /// line. Also pulls in `__MEMZERO` for clearing arrays.
    used_run: bool,
    /// True iff any `CLR` statement was emitted. Pulls in the
    /// `__STATE_RESET` helper (also reused by RUN's restart path).
    used_state_reset: bool,
    /// True iff any FOR loop's STEP was dynamic (didn't fold to a
    /// literal). Pulls in the per-FOR sign-byte slot allocations.
    used_dyn_step: bool,
    /// True iff any integer-array element was read in expression
    /// context. Pulls in the `__ARRAY_INT_TMP` 1-byte slot used to
    /// stash the lo byte while the hi byte is loaded for GIVAYF.
    used_array_int_tmp: bool,
    /// True iff a call site used the int16 SGN helper.
    used_sgn_int16: bool,
    /// True iff `__HEAP_INIT` emitted a string-array initialiser. Pulls
    /// in the `__FILL_EMPTY_STR` helper which fills a 2-byte slot run
    /// with &__EMPTY_STR.
    used_fill_empty_str: bool,
    /// Line number of the program's first line — `__RUN_RESTART` JMPs
    /// to `L<first_line>` after re-initialising state. Captured during
    /// `run()`; 0 if the module has no lines (in which case `RUN`
    /// itself is unreachable so the field is never read).
    first_line: u16,
    line_numbers: Vec<u16>,
    uses_rcomp: bool,
    /// Optimisation profile selected by the caller (CLI flag). Drives
    /// any size-vs-speed branch in codegen; pure win-win paths ignore
    /// it. Currently stored but not yet branched on — wired so future
    /// optimisations can read it without re-plumbing.
    #[allow(dead_code)]
    profile: Profile,
    /// `*=$XXXX` directive value emitted at the head of the assembly.
    /// Defaults to [`CODE_ORIGIN`]; the custom-start-address path
    /// overrides it after construction via [`emit_with_profile_at`].
    code_origin: u16,
    /// True iff anything needs the shared `__DIV_BY_10` byte-mod-10
    /// helper. Multiple call sites (TI$ formatter, PRINT-comma).
    used_div_by_10: bool,
    /// Float scalars that range analysis proved are always int16. In
    /// Speed profile we keep a 2-byte shadow slot beside the normal
    /// 5-byte BASIC float slot so int-island paths can read them
    /// without a FAC roundtrip while ordinary BASIC-visible reads still
    /// see the float slot.
    shadow_int_vars: HashMap<VarName, String>,
    /// Labels promoted to zero-page slots. Each entry maps a slot
    /// label (e.g., `__SI_V_A`) to its ZP base address. ZP-resident
    /// labels emit as `<label> = $XX` near the binary's start so
    /// every `LDA <label>` / `STA <label>` / `<label>+1` reference
    /// resolves to a 2-byte ZP instruction at assembly time —
    /// 1 byte and 1 cycle smaller than the absolute form.
    /// `__STATE_RESET` clears these byte-by-byte before main.
    zp_promotions: Vec<(String, u8, usize)>,
    /// Integer variables whose `V_<base>` slot was placed in zero
    /// page. `intern_var` skips appending these to `vars_order` so
    /// the absolute BSS slot isn't also emitted.
    zp_int_vars: HashSet<VarName>,
    /// Integer scalars whose complete write set is range-proved to
    /// fit in a single byte (256 distinct values inside [-128, 255]).
    /// These use a one-byte slot. The subset in `signed_byte_int_vars`
    /// can hold negative values and needs sign-extension on widening;
    /// vars in this set but NOT in the signed subset are pure
    /// unsigned u8 [0, 255] and widen with `LDA #$00`.
    u8_int_vars: HashSet<VarName>,
    /// Subset of `u8_int_vars` whose range includes negative values.
    /// Reading the high byte from these requires sign-extension
    /// (bit 7 of the byte → $00 or $FF) rather than the cheaper
    /// `LDA #$00` used for pure u8 vars.
    signed_byte_int_vars: HashSet<VarName>,
    /// Names of all `__SXT_TMP_<n>` scratch slots used by the i16
    /// add/sub path to materialise the sign-extended hi byte of a
    /// signed-u8 var operand before the ADC/SBC chain. Each one
    /// gets a single-byte BSS reservation in the trailing data
    /// section. Cleared per compile run.
    signed_u8_sxt_scratches: HashSet<String>,
    /// Free zero-page bytes still available for promotion. Drained
    /// by `collect_shadow_ints`, `collect_zp_int_vars`, and the
    /// FOR-counter pre-pass; whichever order picks first wins.
    ///
    /// The pool is computed per-module from a feature scan in
    /// `compute_zp_pool` so we only claim addresses that are actually
    /// safe for THIS program. The "always-safe" core lives in BASIC-
    /// interpreter scratch we never touch ($02, $08-$0C, $13,
    /// $16-$21); everything else is conditionally added when the
    /// program demonstrably doesn't use the feature that owns it.
    zp_pool: Vec<u8>,
    /// `for_int_slots` IDs whose FI_<n> slot landed in zero page
    /// (populated by the FOR-counter pre-pass and consumed at
    /// `emit_for_int`).
    zp_int_for_assignments: HashMap<usize, u8>,
    /// `for_u8_slots` IDs whose FU_<n> slot landed in zero page.
    zp_u8_for_assignments: HashMap<usize, u8>,
    /// FOR-counter ZP slots handed out so far, available for reuse by a
    /// later FOR counter whose loop variable doesn't interfere with any
    /// current owner. A FOR loop always initialises its counter at loop
    /// entry before any read, so sharing a slot between non-overlapping
    /// loops is sound (no reliance on a default value left in the slot).
    /// Only FOR-counter slots live here — scalar / shadow slots aren't
    /// reused (they'd need a defined-before-use proof, not just
    /// liveness).
    zp_for_reuse_slots: Vec<ZpReuseSlot>,
    /// Hot Integer-var ZP slots available for sharing by a later hot
    /// Integer var that is both non-interfering and proven
    /// defined-before-use. Only the first few vars take a fresh pool
    /// byte; additional safe candidates alias one of these instead of
    /// falling back to BSS.
    zp_int_reuse_slots: Vec<ZpReuseSlot>,
    /// Cached IR analyses shared by all codegen decisions. Built once
    /// via the analysis registry so later codegen fast paths can query
    /// facts without running their own ad-hoc walks.
    analysis: CodegenAnalysis,
    /// CFG node/path for the statement currently being emitted. These
    /// are set by `emit_stmt_at_path`, including nested IF bodies, and
    /// let expression-level helpers read per-statement numeric facts.
    current_stmt_node: Option<usize>,
    current_stmt_path: Option<crate::cfg::StmtPath>,
}

#[derive(Clone)]
struct CodegenAnalysis {
    numeric_facts: crate::dataflow::NumericFactsResult,
    effects: crate::analysis::EffectSummaryResult,
    /// Variable interference graph (from `LiveVars`). Used by the
    /// FOR-counter ZP allocator to let counters whose loop variables
    /// are never simultaneously live share a single zero-page slot.
    interference: crate::dataflow::InterferenceGraph,
    /// Variables proven always-written-before-read (forward
    /// must-analysis). Only these may *share* a sole-storage ZP slot —
    /// a variable that can read its slot before writing it would
    /// otherwise observe a co-tenant's bytes instead of the default 0.
    defined_before_use: std::collections::HashSet<VarName>,
}

impl CodegenAnalysis {
    fn from_module(module: &ir::Module) -> Self {
        let mut registry = crate::analysis::Registry::new();
        let numeric_facts = registry
            .get(module, &crate::dataflow::NumericFactAnalysis)
            .clone();
        let effects = registry
            .get(module, &crate::analysis::EffectSummaryAnalysis)
            .clone();
        let interference = registry
            .get(module, &crate::dataflow::VarInterference)
            .clone();
        let defined_before_use = registry
            .get(module, &crate::dataflow::DefinedBeforeUse)
            .clone();
        Self {
            numeric_facts,
            effects,
            interference,
            defined_before_use,
        }
    }
}

/// One reusable zero-page slot and the set of variables that share it.
/// A new variable may join iff it interferes with none of `vars`.
/// Used for two pools: FOR-counter slots (safe because a FOR always
/// writes its counter before the body reads it) and hot Integer-var
/// slots (safe only for variables proven defined-before-use).
#[derive(Debug, Clone)]
struct ZpReuseSlot {
    addr: u8,
    /// Slot width in bytes: 2 for an int slot, 1 for a u8 slot.
    size: u8,
    vars: Vec<VarName>,
}

/// Find an existing slot of the requested `size` that `var` can safely
/// reuse — i.e. one where every current owner is non-interfering with
/// `var`. Returns the index into `slots`, or `None` when `var` needs
/// its own slot. Pure (no `self`) so the decision is unit-testable in
/// isolation. Callers are responsible for any additional soundness
/// gate (e.g. defined-before-use) before offering a var to this pool.
fn find_reuse_slot(
    slots: &[ZpReuseSlot],
    size: u8,
    var: &VarName,
    interference: &crate::dataflow::InterferenceGraph,
) -> Option<usize> {
    slots.iter().position(|slot| {
        slot.size == size
            && slot
                .vars
                .iter()
                .all(|owner| !interference.interferes(owner, var))
    })
}

#[derive(Debug, Clone)]
struct DefFnInfo {
    param: VarName,
    body: Expr,
}

#[derive(Clone)]
enum ForFrame {
    /// FAC-based loop: counter, end, and step all live in MFLPT slots
    /// and the per-NEXT increment goes through FADD. Used for any loop
    /// whose start/end/step isn't a small integer literal.
    Float(FloatForFrame),
    /// Native 16-bit integer loop: counter is two ZP-style bytes,
    /// increment is CLC/ADC, exit-test is a signed 16-bit compare.
    /// V_var is synced from the int counter at every NEXT so the body
    /// can still read the loop variable as a float.
    Int(IntForFrame),
    /// 8-bit unsigned integer loop: counter is one byte, end-test is
    /// a single CMP, and literal STEP is applied with INC/DEC or
    /// ADC/SBC immediate. Picked when start/end fit in `[0, 255]`
    /// and the step lands exactly on END.
    U8(U8ForFrame),
}

#[derive(Clone, Debug)]
struct StructuredLoopFrame {
    kind: StructuredLoopKind,
    top_label: String,
    exit_label: String,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum StructuredLoopKind {
    Repeat,
    Loop,
}

#[derive(Clone, Debug)]
struct DoFrame {
    else_label: String,
    end_label: String,
    seen_else: bool,
}

#[derive(Clone)]
struct FloatForFrame {
    var: VarName,
    end_slot_label: String,
    step_loc: StepLoc,
    top_label: String,
    exit_label: String,
    induction: Option<InductionFrame>,
    array_pointers: Vec<ArrayPtrFrame>,
}

/// Per-FOR strength-reduction state for `var * K` (constant K).
/// `slot_label` names a 5-byte float slot that holds the running
/// value of `var * K`: initialised at the FOR header, advanced by
/// `step * K` inside NEXT. `k_value` is the literal multiplier and
/// is matched against `Bin(Mul, Var(var), Number(k))` /
/// `Bin(Mul, Number(k), Var(var))` shapes during expression
/// emission so codegen can swap the multiply for a single MOVFM
/// from the slot.
#[derive(Clone, Debug)]
struct InductionFrame {
    k_value: f64,
    slot_label: String,
}

/// Per-FOR running pointer for array accesses with one loop-var axis.
/// `slot_label` names a 2-byte ZP-pointer slot that holds the live
/// address of the base shape at the current FOR counter. Use sites
/// match the same literal-axis indexes and a `loop_var + const` on the
/// live axis, then add the scaled offset from that const.
#[derive(Clone, Debug)]
struct ArrayPtrFrame {
    array_name: VarName,
    slot_label: String,
    indices: Vec<ArrayInductionIndex>,
    byte_strides: Vec<i32>,
    advance_bytes_per_step: i32,
}

/// Where a FOR loop's STEP value lives at runtime.
#[derive(Clone)]
enum StepLoc {
    /// Constant STEP — `pool_label` points at a shared MFLPT in the
    /// constant pool, and `value` lets NEXT pick its exit-sign branch
    /// at compile time (no runtime sign byte needed).
    Const { pool_label: String, value: f64 },
    /// Dynamic STEP — `slot_label` is a per-FOR MFLPT that was filled
    /// by the FOR header, and `sign_label` is the byte stamped at the
    /// same time so NEXT can pick the exit-sign branch by reading it.
    Dynamic {
        slot_label: String,
        sign_label: String,
    },
}

/// A leaf operand that the int16 fast path knows how to read with a
/// single LDA. `Imm` is split into lo/hi bytes at the use site; `Var`
/// resolves through `intern_var` to the var's slot label; `Mem` is a
/// raw 2-byte memory slot referenced by literal label (used by the
/// integer-island lowering for temporary results that don't have a
/// `VarName`).
#[derive(Clone, PartialEq, Eq)]
enum Int16Operand {
    Imm(i16),
    Var(VarName),
    Mem(String),
    /// Single-byte memory location whose 16-bit value is `(0, byte)`
    /// (high byte is implicitly zero). Generated for active u8-FOR
    /// counters (FU_<n>) — by construction the value fits in u8 and
    /// the high byte is always $00. Loaders emit `LDA <label>` for
    /// the low byte and `LDA #$00` for the high byte.
    MemU8(String),
}

/// Optimisation profile selected by the frontend. Drives the
/// size-vs-speed trade-off for any optimisation where the two pull in
/// opposite directions; pure win-win optimisations stay on under all
/// profiles.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Profile {
    /// Win-win only — every optimisation is both smaller AND faster.
    #[default]
    Default,
    /// Allow optimisations that grow the binary if they make it faster
    /// (e.g. inlined helpers, unrolled hot loops).
    Speed,
    /// Allow optimisations that shrink the binary even when slower
    /// (e.g. JSR-into-shared-helper for repeated int math).
    Size,
}

/// Where the int-FOR's end value lives at runtime. Keeps the
/// fast-path bytes tight when end folds to a literal (NEXT uses
/// `CMP #imm`); falls back to a 2-byte BSS slot when the expression
/// is dynamic but range analysis proves it fits i16 (NEXT uses
/// `CMP <slot>`).
#[derive(Clone)]
enum IntForEnd {
    Literal(i16),
    Slot(String),
}

#[derive(Clone)]
struct IntForFrame {
    var: VarName,
    counter_label: String,
    start_value: i16,
    end: IntForEnd,
    step_value: i16,
    top_label: String,
    exit_label: String,
    /// If false, the loop body never reads V_var, so the per-iteration
    /// sync can be skipped. We still emit one sync at the exit label so
    /// post-loop code sees the correct final value.
    body_reads_loop_var: bool,
    induction: Option<InductionFrame>,
    array_pointers: Vec<ArrayPtrFrame>,
}

/// Where a u8-FOR's end value lives. Literal ends keep the tight
/// immediate `CMP #imm`; dynamic-but-range-proved-u8 ends use the
/// first byte of an `FE_<n>` slot.
#[derive(Clone, Debug)]
enum U8ForEnd {
    Literal(u8),
    Slot(String),
}

impl U8ForEnd {
    fn literal(&self) -> Option<u8> {
        match self {
            U8ForEnd::Literal(v) => Some(*v),
            U8ForEnd::Slot(_) => None,
        }
    }
}

/// 8-bit FOR-loop frame. Counter is a single byte; loop overhead is
/// roughly 60% smaller than the 16-bit `IntForFrame`. We pick this
/// shape when start/end both fit in `[0, 255]`, the literal step fits
/// in one byte, and the selected exit mode can preserve the post-loop
/// value without byte wrap.
#[derive(Clone)]
struct U8ForFrame {
    var: VarName,
    /// 1-byte slot. Allocated in the BSS run alongside int-FOR slots,
    /// labelled `FU_<n>` so the slot table at end-of-binary
    /// distinguishes them from `FI_<n>`.
    counter_label: String,
    start_value: u8,
    end: U8ForEnd,
    /// Non-zero literal step whose magnitude fits in u8.
    step_value: i16,
    /// Exact-hit literal loops keep the old compact pre-step equality
    /// test. Non-exact or dynamic-end loops advance first, then exit
    /// after crossing the inclusive bound.
    exact_hit: bool,
    top_label: String,
    exit_label: String,
    body_reads_loop_var: bool,
    induction: Option<InductionFrame>,
    array_pointers: Vec<ArrayPtrFrame>,
}

impl ForFrame {
    fn var(&self) -> &VarName {
        match self {
            ForFrame::Float(f) => &f.var,
            ForFrame::Int(f) => &f.var,
            ForFrame::U8(f) => &f.var,
        }
    }

    fn with_fresh_exit(&self, exit_label: String) -> ForFrame {
        match self {
            ForFrame::Float(f) => {
                let mut g = f.clone();
                g.exit_label = exit_label;
                ForFrame::Float(g)
            }
            ForFrame::Int(f) => {
                let mut g = f.clone();
                g.exit_label = exit_label;
                ForFrame::Int(g)
            }
            ForFrame::U8(f) => {
                let mut g = f.clone();
                g.exit_label = exit_label;
                ForFrame::U8(g)
            }
        }
    }
}

