            writeln!(self.code, "    LDX #$10").unwrap();
            writeln!(self.code, "__DIV16_LOOP:").unwrap();
            writeln!(self.code, "    ASL $14").unwrap();
            writeln!(self.code, "    ROL $15").unwrap();
            writeln!(self.code, "    ROL __DIV16_REM").unwrap();
            writeln!(self.code, "    ROL __DIV16_REM+1").unwrap();
