            writeln!(self.code, "    ORA __DIV16_REM+1").unwrap();
            writeln!(self.code, "    BEQ __DIV16_DONE").unwrap();
            writeln!(self.code, "    SEC").unwrap();
            writeln!(self.code, "    LDA #$00").unwrap();
            writeln!(self.code, "    SBC __DIV16_REM").unwrap();
            writeln!(self.code, "    STA __DIV16_REM").unwrap();
            writeln!(self.code, "    LDA #$00").unwrap();
            writeln!(self.code, "    SBC __DIV16_REM+1").unwrap();
            writeln!(self.code, "    STA __DIV16_REM+1").unwrap();
