            writeln!(self.code, "    STA __TSB_RECT_ROW").unwrap();
            writeln!(self.code, "    LDA __TSB_SCROLL_COL").unwrap();
            writeln!(self.code, "    CLC").unwrap();
            writeln!(self.code, "    ADC __TSB_SCROLL_W").unwrap();
            writeln!(self.code, "    SEC").unwrap();
            writeln!(self.code, "    SBC #$01").unwrap();
            writeln!(self.code, "    STA __TSB_RECT_COL").unwrap();
            writeln!(self.code, "    LDA #$01").unwrap();
            writeln!(self.code, "    STA __TSB_RECT_W").unwrap();
            writeln!(self.code, "    LDA __TSB_SCROLL_H").unwrap();
            writeln!(self.code, "    STA __TSB_RECT_H").unwrap();
