            writeln!(self.code, "__TRS_SAVE_ROW:").unwrap();
            writeln!(self.code, "    JSR __TSB_RECT_ADDR").unwrap();
            writeln!(self.code, "    LDY #$00").unwrap();
            writeln!(self.code, "__TRS_SR_LOOP:").unwrap();
            writeln!(self.code, "    CPY __TSB_RECT_W").unwrap();
            writeln!(self.code, "    BEQ __TRS_SR_DONE").unwrap();
            writeln!(self.code, "    LDA (${:02X}),Y", rt::ARRAY_ADDR_LO).unwrap();
            writeln!(self.code, "    STA __TSB_SCROLL_BUF,Y").unwrap();
            writeln!(self.code, "    INY").unwrap();
            writeln!(self.code, "    BNE __TRS_SR_LOOP").unwrap();
            writeln!(self.code, "__TRS_SR_DONE:").unwrap();
            writeln!(self.code, "    RTS").unwrap();
            writeln!(self.code, "__TRS_RESTORE_ROW:").unwrap();
            writeln!(self.code, "    JSR __TSB_RECT_ADDR").unwrap();
            writeln!(self.code, "    LDY #$00").unwrap();
            writeln!(self.code, "__TRS_RR_LOOP:").unwrap();
            writeln!(self.code, "    CPY __TSB_RECT_W").unwrap();
            writeln!(self.code, "    BEQ __TRS_DONE").unwrap();
            writeln!(self.code, "    LDA __TSB_SCROLL_BUF,Y").unwrap();
            writeln!(self.code, "    STA (${:02X}),Y", rt::ARRAY_ADDR_LO).unwrap();
            writeln!(self.code, "    INY").unwrap();
            writeln!(self.code, "    BNE __TRS_RR_LOOP").unwrap();
            // The W <= 255 invariant means the BNE-not-taken
            // fall-through is unreachable today, but keep an explicit
            // RTS so a future change that loosens W's range can't
            // silently drop into __TRS_SAVE_COL.
            writeln!(self.code, "    RTS").unwrap();
