            writeln!(self.code, "    LDX #$00").unwrap();
            writeln!(self.code, "__TRS_SC_LOOP:").unwrap();
            writeln!(self.code, "    CPX __TSB_SCROLL_H").unwrap();
            writeln!(self.code, "    BEQ __TRS_SC_DONE").unwrap();
            writeln!(self.code, "    LDY #$00").unwrap();
            writeln!(self.code, "    LDA (${:02X}),Y", rt::ARRAY_ADDR_LO).unwrap();
            writeln!(self.code, "    STA __TSB_SCROLL_BUF,X").unwrap();
            writeln!(self.code, "    JSR __TRS_ADD40_DEST").unwrap();
            writeln!(self.code, "    INX").unwrap();
            writeln!(self.code, "    BNE __TRS_SC_LOOP").unwrap();
            writeln!(self.code, "__TRS_SC_DONE:").unwrap();
            writeln!(self.code, "    RTS").unwrap();
            writeln!(self.code, "__TRS_RESTORE_COL:").unwrap();
            writeln!(self.code, "    JSR __TSB_RECT_ADDR").unwrap();
            writeln!(self.code, "    LDX #$00").unwrap();
            writeln!(self.code, "__TRS_RC_LOOP:").unwrap();
            writeln!(self.code, "    CPX __TSB_SCROLL_H").unwrap();
