            writeln!(self.code, "    SEC").unwrap();
            writeln!(self.code, "    LDA __CIRC_REM").unwrap();
            writeln!(self.code, "    SBC __CIRC_STEP").unwrap();
            writeln!(self.code, "    STA __CIRC_REM").unwrap();
            writeln!(self.code, "    LDA __CIRC_REM+1").unwrap();
            writeln!(self.code, "    SBC #$00").unwrap();
            writeln!(self.code, "    STA __CIRC_REM+1").unwrap();
