            writeln!(self.code, "    LDA __CIRC_A").unwrap();
            writeln!(self.code, "    CLC").unwrap();
            writeln!(self.code, "    ADC __CIRC_STEP").unwrap();
            writeln!(self.code, "    STA __CIRC_A").unwrap();
            writeln!(self.code, "    JSR __CIRC_PT").unwrap();
            // LINE from cursor to new point.
            writeln!(self.code, "    LDA __CIRC_CURX").unwrap();
            writeln!(self.code, "    STA __LINE_X1").unwrap();
            writeln!(self.code, "    LDA __CIRC_CURX+1").unwrap();
            writeln!(self.code, "    STA __LINE_X1+1").unwrap();
            writeln!(self.code, "    LDA __CIRC_CURY").unwrap();
            writeln!(self.code, "    STA __LINE_Y1").unwrap();
            writeln!(self.code, "    LDA __CIRC_PX").unwrap();
            writeln!(self.code, "    STA __LINE_X2").unwrap();
            writeln!(self.code, "    LDA __CIRC_PX+1").unwrap();
            writeln!(self.code, "    STA __LINE_X2+1").unwrap();
            writeln!(self.code, "    LDA __CIRC_PY").unwrap();
            writeln!(self.code, "    STA __LINE_Y2").unwrap();
            writeln!(self.code, "    JSR __LINE").unwrap();
            // Cursor := new point.
            writeln!(self.code, "    LDA __CIRC_PX").unwrap();
            writeln!(self.code, "    STA __CIRC_CURX").unwrap();
            writeln!(self.code, "    LDA __CIRC_PX+1").unwrap();
            writeln!(self.code, "    STA __CIRC_CURX+1").unwrap();
            writeln!(self.code, "    LDA __CIRC_PY").unwrap();
            writeln!(self.code, "    STA __CIRC_CURY").unwrap();
            writeln!(self.code, "    JMP __CIRC_ARC_LOOP").unwrap();
            writeln!(self.code, "__CIRC_ARC_DONE:").unwrap();
