            writeln!(self.code, "    STA __ANGL_M").unwrap();
            writeln!(self.code, "    LDA __CIRC_R").unwrap();
            writeln!(self.code, "    STA __ANGL_N").unwrap();
            writeln!(self.code, "    JSR __ANGL_MULDIV").unwrap();
            writeln!(self.code, "    CLC").unwrap();
            writeln!(self.code, "    LDA __CIRC_CX").unwrap();
            writeln!(self.code, "    ADC __ANGL_R").unwrap();
            writeln!(self.code, "    STA __CIRC_PX").unwrap();
            writeln!(self.code, "    LDA __CIRC_CX+1").unwrap();
            writeln!(self.code, "    ADC __ANGL_R+1").unwrap();
            writeln!(self.code, "    STA __CIRC_PX+1").unwrap();
