            writeln!(self.code, "    AND #$FD").unwrap();
            writeln!(self.code, "    STA $01").unwrap();
            writeln!(self.code, "    LDA #$01").unwrap();
            writeln!(self.code, "    STA __DRAW_NOBANK").unwrap();
            writeln!(self.code, "    LDA #$00").unwrap();
            writeln!(self.code, "    STA __DUP_RY").unwrap();
            writeln!(self.code, "__DUP_ROW:").unwrap();
            writeln!(self.code, "    LDA #$00").unwrap();
            writeln!(self.code, "    STA __DUP_RX").unwrap();
            writeln!(self.code, "__DUP_COL:").unwrap();
            // src_x = __DUP_SX + __DUP_RX (16-bit + 8-bit unsigned)
            writeln!(self.code, "    CLC").unwrap();
