            writeln!(self.code, "    LDA #$00").unwrap();
            writeln!(self.code, "    LDX __DUP_RX").unwrap();
            writeln!(self.code, "    BEQ __DUP_BLKX_DONE").unwrap();
            writeln!(self.code, "__DUP_BLKX_MUL:").unwrap();
