            writeln!(self.code, "    ADC __DUP_ZOOM").unwrap();
            writeln!(self.code, "    DEX").unwrap();
            writeln!(self.code, "    BNE __DUP_BLKX_MUL").unwrap();
            writeln!(self.code, "__DUP_BLKX_DONE:").unwrap();
            writeln!(self.code, "    CLC").unwrap();
            writeln!(self.code, "    ADC __DUP_DX").unwrap();
            writeln!(self.code, "    STA __DUP_BLKX").unwrap();
