            writeln!(self.code, "    LDX __DUP_RY").unwrap();
            writeln!(self.code, "    BEQ __DUP_BLKY_DONE").unwrap();
            writeln!(self.code, "__DUP_BLKY_MUL:").unwrap();
            writeln!(self.code, "    CLC").unwrap();
            writeln!(self.code, "    ADC __DUP_ZOOM").unwrap();
            writeln!(self.code, "    DEX").unwrap();
            writeln!(self.code, "    BNE __DUP_BLKY_MUL").unwrap();
            writeln!(self.code, "__DUP_BLKY_DONE:").unwrap();
            writeln!(self.code, "    CLC").unwrap();
            writeln!(self.code, "    ADC __DUP_DY").unwrap();
            writeln!(self.code, "    STA __DUP_BLKY").unwrap();
