            writeln!(self.code, "    LDA #$00").unwrap();
            writeln!(self.code, "    STA __DUP_BY").unwrap();
            writeln!(self.code, "__DUP_BLK_ROW:").unwrap();
            writeln!(self.code, "    CLC").unwrap();
            writeln!(self.code, "    LDA __DUP_BLKY").unwrap();
            writeln!(self.code, "    ADC __DUP_BY").unwrap();
            writeln!(self.code, "    STA __DRAW_Y").unwrap();
            writeln!(self.code, "    LDA #$00").unwrap();
            writeln!(self.code, "    STA __DUP_BX").unwrap();
            writeln!(self.code, "__DUP_BLK_COL:").unwrap();
            writeln!(self.code, "    CLC").unwrap();
            writeln!(self.code, "    LDA __DUP_BLKX").unwrap();
            writeln!(self.code, "    ADC __DUP_BX").unwrap();
            writeln!(self.code, "    STA __DRAW_X").unwrap();
            writeln!(self.code, "    LDA __DUP_BLKX+1").unwrap();
            writeln!(self.code, "    ADC #$00").unwrap();
            writeln!(self.code, "    STA __DRAW_X+1").unwrap();
            writeln!(self.code, "    JSR __DRAW").unwrap();
            writeln!(self.code, "    INC __DUP_BX").unwrap();
            writeln!(self.code, "    LDA __DUP_BX").unwrap();
            writeln!(self.code, "    CMP __DUP_ZOOM").unwrap();
            writeln!(self.code, "    BCC __DUP_BLK_COL").unwrap();
            writeln!(self.code, "    INC __DUP_BY").unwrap();
            writeln!(self.code, "    LDA __DUP_BY").unwrap();
            writeln!(self.code, "    CMP __DUP_ZOOM").unwrap();
            writeln!(self.code, "    BCC __DUP_BLK_ROW").unwrap();
            writeln!(self.code, "__DUP_NEXT:").unwrap();
            writeln!(self.code, "    INC __DUP_RX").unwrap();
            writeln!(self.code, "    LDA __DUP_RX").unwrap();
            writeln!(self.code, "    CMP __DUP_W").unwrap();
            writeln!(self.code, "    BCC __DUP_COL").unwrap();
            writeln!(self.code, "    INC __DUP_RY").unwrap();
            writeln!(self.code, "    LDA __DUP_RY").unwrap();
            writeln!(self.code, "    CMP __DUP_H").unwrap();
            writeln!(self.code, "    BCC __DUP_ROW").unwrap();
