            writeln!(self.code, "    STA __DRAW_NOBANK").unwrap();
            writeln!(self.code, "    PLA").unwrap();
            writeln!(self.code, "    STA $01").unwrap();
            writeln!(self.code, "    CLI").unwrap();
            writeln!(self.code, "    RTS").unwrap();
