            writeln!(self.code, "__ANGL:").unwrap();
            writeln!(self.code, "    LDA __ANGL_A").unwrap();
            writeln!(self.code, "    JSR __ANGL_SIN").unwrap();
            writeln!(self.code, "    STA __ANGL_SY").unwrap();
            writeln!(self.code, "    CLC").unwrap();
            writeln!(self.code, "    LDA __ANGL_A").unwrap();
            writeln!(self.code, "    ADC #$40").unwrap();
            writeln!(self.code, "    JSR __ANGL_SIN").unwrap();
            writeln!(self.code, "    STA __ANGL_SX").unwrap();
            // dx = cos(angle) * rx / 64.
            writeln!(self.code, "    LDA __ANGL_SX").unwrap();
            writeln!(self.code, "    STA __ANGL_M").unwrap();
            writeln!(self.code, "    LDA __ANGL_LX").unwrap();
            writeln!(self.code, "    STA __ANGL_N").unwrap();
            writeln!(self.code, "    JSR __ANGL_MULDIV").unwrap();
            writeln!(self.code, "    LDA __ANGL_R").unwrap();
            writeln!(self.code, "    STA __ANGL_DX").unwrap();
            writeln!(self.code, "    LDA __ANGL_R+1").unwrap();
            writeln!(self.code, "    STA __ANGL_DX+1").unwrap();
