            writeln!(self.code, "    JSR __HEX_BYTE").unwrap();
            writeln!(self.code, "    LDA #$03").unwrap();
            writeln!(self.code, "    JMP __INT_TO_HEX_FIN").unwrap();
            writeln!(self.code, "__INT_TO_HEX_LONG:").unwrap();
            writeln!(self.code, "    LDY #$00").unwrap();
            writeln!(self.code, "    LDA #$04").unwrap();
            writeln!(self.code, "    STA ($FD),Y").unwrap();
            writeln!(self.code, "    INY").unwrap();
            writeln!(self.code, "    LDA ${:02X}", rt::LINNUM_HI).unwrap();
            writeln!(self.code, "    JSR __HEX_BYTE").unwrap();
            writeln!(self.code, "    LDA ${:02X}", rt::LINNUM_LO).unwrap();
            writeln!(self.code, "    JSR __HEX_BYTE").unwrap();
            writeln!(self.code, "    LDA #$05").unwrap();
            writeln!(self.code, "__INT_TO_HEX_FIN:").unwrap();
