            writeln!(self.code, "    PLA").unwrap();
            writeln!(self.code, "    AND #$0F").unwrap();
            writeln!(self.code, "    JSR __HEX_NIBBLE").unwrap();
            writeln!(self.code, "    STA ($FD),Y").unwrap();
            writeln!(self.code, "    INY").unwrap();
            writeln!(self.code, "    RTS").unwrap();
            writeln!(self.code, "__HEX_NIBBLE:").unwrap();
            writeln!(self.code, "    CMP #$0A").unwrap();
            writeln!(self.code, "    BCC __HEX_NIB_DIG").unwrap();
            writeln!(self.code, "    ADC #$06").unwrap();
            writeln!(self.code, "__HEX_NIB_DIG:").unwrap();
            writeln!(self.code, "    ADC #$30").unwrap();
            writeln!(self.code, "    RTS").unwrap();
