            writeln!(self.code, "    STA $FD").unwrap();
            writeln!(self.code, "    LDA __HEAP_PTR+1").unwrap();
            writeln!(self.code, "    STA $FE").unwrap();
            writeln!(self.code, "    LDA ${:02X}", rt::LINNUM_HI).unwrap();
            writeln!(self.code, "    BNE __INT_TO_BIN_LONG").unwrap();
            writeln!(self.code, "    LDY #$00").unwrap();
            writeln!(self.code, "    LDA #$08").unwrap();
            writeln!(self.code, "    STA ($FD),Y").unwrap();
            writeln!(self.code, "    INY").unwrap();
            writeln!(self.code, "    LDA ${:02X}", rt::LINNUM_LO).unwrap();
            writeln!(self.code, "    JSR __BIN_BYTE").unwrap();
            writeln!(self.code, "    LDA #$09").unwrap();
            writeln!(self.code, "    JMP __INT_TO_BIN_FIN").unwrap();
            writeln!(self.code, "__INT_TO_BIN_LONG:").unwrap();
            writeln!(self.code, "    LDY #$00").unwrap();
            writeln!(self.code, "    LDA #$10").unwrap();
            writeln!(self.code, "    STA ($FD),Y").unwrap();
            writeln!(self.code, "    INY").unwrap();
            writeln!(self.code, "    LDA ${:02X}", rt::LINNUM_HI).unwrap();
            writeln!(self.code, "    JSR __BIN_BYTE").unwrap();
            writeln!(self.code, "    LDA ${:02X}", rt::LINNUM_LO).unwrap();
            writeln!(self.code, "    JSR __BIN_BYTE").unwrap();
            writeln!(self.code, "    LDA #$11").unwrap();
            writeln!(self.code, "__INT_TO_BIN_FIN:").unwrap();
            writeln!(self.code, "    CLC").unwrap();
            writeln!(self.code, "    ADC __HEAP_PTR").unwrap();
            writeln!(self.code, "    STA __HEAP_PTR").unwrap();
            writeln!(self.code, "    BCC __INT_TO_BIN_NCY").unwrap();
            writeln!(self.code, "    INC __HEAP_PTR+1").unwrap();
            writeln!(self.code, "__INT_TO_BIN_NCY:").unwrap();
            writeln!(self.code, "    LDA $FD").unwrap();
