            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__MEMZERO_PTR_HI:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__MEMZERO_CNT_LO:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__MEMZERO_CNT_HI:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
