            writeln!(self.code, "__PFL_PTR_LO:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__PFL_PTR_HI:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__PFL_CNT_LO:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__PFL_CNT_HI:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__PFL_END_LO:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__PFL_END_HI:").unwrap();
