            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__STR_SRC_HI:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__STR_OWNER_LO:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__STR_OWNER_HI:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
