            writeln!(self.code, "__MUSIC_OCT:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__MUSIC_FREQ:").unwrap();
            writeln!(self.code, "    .byte $00,$00").unwrap();
            // Music player state — per-note duration / tempo gap /
            // active voice. WAVETAB caches the last WAVE statement
            // per voice (without gate bit) so gateon/gateoff can
            // toggle the gate without losing the waveform.
            writeln!(self.code, "__MUSIC_DUR:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__MUSIC_DUR_BAK:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__MUSIC_TEMPO_CTR:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__MUSIC_STRSAVE:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__MUSIC_VOICE:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__MUSIC_VOFFS:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__MUSIC_WAVETAB:").unwrap();
            writeln!(self.code, "    .byte $00,$00,$00").unwrap();
