            writeln!(self.code, "    .byte $10").unwrap();
            writeln!(self.code, "__BFLASH_COUNT:").unwrap();
            writeln!(self.code, "    .byte $10").unwrap();
            writeln!(self.code, "__BFLASH_C1:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__BFLASH_C2:").unwrap();
            writeln!(self.code, "    .byte $01").unwrap();
