            writeln!(self.code, "; --- memory copy state ---").unwrap();
            writeln!(self.code, "__MC_SRC:").unwrap();
            writeln!(self.code, "    .byte $00,$00").unwrap();
            writeln!(self.code, "__MC_DST:").unwrap();
            writeln!(self.code, "    .byte $00,$00").unwrap();
            writeln!(self.code, "__MC_LEN:").unwrap();
            writeln!(self.code, "    .byte $00,$00").unwrap();
