            writeln!(self.code, "__TSB_RECT_ROW:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__TSB_RECT_COL:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__TSB_RECT_W:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__TSB_RECT_H:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__TSB_RECT_VAL:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__TSB_RECT_BASE_LO:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__TSB_RECT_BASE_HI:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__TSB_RECT_ROWS:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
