                writeln!(self.code, "__TSB_RECT_SRC_COL:").unwrap();
                writeln!(self.code, "    .byte $00").unwrap();
                writeln!(self.code, "__TSB_RECT_DEST_ROW:").unwrap();
                writeln!(self.code, "    .byte $00").unwrap();
                writeln!(self.code, "__TSB_RECT_DEST_COL:").unwrap();
                writeln!(self.code, "    .byte $00").unwrap();
