                writeln!(self.code, "    .byte $00").unwrap();
                writeln!(self.code, "__TSB_SCROLL_COL:").unwrap();
                writeln!(self.code, "    .byte $00").unwrap();
                writeln!(self.code, "__TSB_SCROLL_W:").unwrap();
                writeln!(self.code, "    .byte $00").unwrap();
                writeln!(self.code, "__TSB_SCROLL_H:").unwrap();
