                writeln!(self.code, "    .byte $00,$00,$00,$00,$00,$00,$00,$00").unwrap();
                writeln!(self.code, "    .byte $00,$00,$00,$00,$00,$00,$00,$00").unwrap();
                writeln!(self.code, "    .byte $00,$00,$00,$00,$00,$00,$00,$00").unwrap();
