            writeln!(self.code, "__DUP_SX:").unwrap();
            writeln!(self.code, "    .byte $00,$00").unwrap();
            writeln!(self.code, "__DUP_SY:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__DUP_W:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__DUP_H:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__DUP_DX:").unwrap();
            writeln!(self.code, "    .byte $00,$00").unwrap();
            writeln!(self.code, "__DUP_DY:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__DUP_ZOOM:").unwrap();
            writeln!(self.code, "    .byte $01").unwrap();
            writeln!(self.code, "__DUP_RX:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__DUP_RY:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__DUP_BX:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
            writeln!(self.code, "__DUP_BY:").unwrap();
            writeln!(self.code, "    .byte $00").unwrap();
