    #[test]
    fn string_let_uses_owner_backref_gc_not_root_scan() {
        let a = svar("A");
        let m = Module {
            lines: vec![Line {
                number: 10,
                stmts: vec![Stmt::LetStr {
                    var: a,
                    value: StrExpr::Dup(
                        Box::new(StrExpr::Literal(b"X".to_vec())),
                        Box::new(Expr::Number(40.0)),
                    ),
                }],
            }],
        };

        let asm = emit_with_profile(&m, Profile::default()).unwrap();

        // `Dup(Literal, N)` writes the owner backref inline and avoids
        // pulling in the heavier `__STR_ASSIGN_OWNED` helper.
        assert!(
            !asm.contains("__STR_ASSIGN_OWNED:"),
            "opt-1 should make the OWNED helper unnecessary\n{asm}"
        );
        assert!(
            asm.contains("    SBC #$02"),
            "owner backref offset (heap_ptr - 2) computed inline\n{asm}"
        );
        // GC machinery still present for the heap.
        assert!(asm.contains("__GC_RUN:"));
        assert!(asm.contains("__HEAP_COPY_SMC:"));
        // No old root-scan GC.
        assert!(!asm.contains("__GC_FIND"));
        assert!(!asm.contains("__GC_SCAN"));
        assert!(!asm.contains("__LASTVAR_PROCESS"));
        assert_assembles(&asm);
    }

