    #[test]
    fn mflpt_canonical_values() {
        assert_eq!(f64_to_mflpt(0.0), [0, 0, 0, 0, 0]);
        assert_eq!(f64_to_mflpt(1.0), [0x81, 0, 0, 0, 0]);
        assert_eq!(f64_to_mflpt(2.0), [0x82, 0, 0, 0, 0]);
        assert_eq!(f64_to_mflpt(5.0), [0x83, 0x20, 0, 0, 0]);
        assert_eq!(f64_to_mflpt(-1.0), [0x81, 0x80, 0, 0, 0]);
        assert_eq!(f64_to_mflpt(0.5), [0x80, 0, 0, 0, 0]);
    }

    #[test]
    fn mflpt_53280_round_trips_to_integer() {
        // 53280 = $D020 (the C64 border-colour register). The encoded
        // MFLPT must decode back to *exactly* 53280 — a fractional
        // residue here would make GETADR truncate to 53279 and PEEK
        // would read the wrong VIC-II register.
        let bytes = f64_to_mflpt(53280.0);
        // Decode: value = (1 + mant31/2^31) * 2^(exp_byte - 0x81)
        let exp = bytes[0] as i32 - 0x81;
        let mant31 = ((bytes[1] as u32 & 0x7F) << 24)
            | ((bytes[2] as u32) << 16)
            | ((bytes[3] as u32) << 8)
            | (bytes[4] as u32);
        let value = (1.0_f64 + (mant31 as f64) / (1u64 << 31) as f64) * 2.0_f64.powi(exp);
        assert_eq!(
            value, 53280.0,
            "MFLPT bytes {bytes:02X?} decoded to {value}"
        );
    }

