    #[test]
    fn codegen_read_supports_string_targets_and_mixed_data() {
        let n = fvar("N");
        let s = svar("S");
        let names = svar("NAMES");
        let m = Module {
            lines: vec![
                Line {
                    number: 10,
                    stmts: vec![Stmt::Dim(vec![DimSpec {
                        name: names.clone(),
                        dims: vec![Expr::Number(0.0)],
                    }])],
                },
                Line {
                    number: 20,
                    stmts: vec![Stmt::Data(vec![
                        DataValue::Float(42.0),
                        DataValue::String(b"ALICE".to_vec()),
                        DataValue::String(b"BOB".to_vec()),
                    ])],
                },
                Line {
                    number: 30,
                    stmts: vec![Stmt::Read(vec![
                        ReadTarget::Scalar(n),
                        ReadTarget::Scalar(s),
                        ReadTarget::Array {
                            name: names,
                            indices: vec![Expr::Number(0.0)],
                        },
                    ])],
                },
            ],
        };
        let asm = emit_with_profile(&m, Profile::default()).unwrap();
        assert!(
            asm.contains("JSR __VAL_HELPER"),
            "numeric READ should parse DATA via VAL\n{asm}"
        );
        assert!(
            asm.contains("STA VS_S"),
            "READ S$ should store DATA pointer low byte\n{asm}"
        );
        assert!(
            asm.contains("STA VS_S+1"),
            "READ S$ should store DATA pointer high byte\n{asm}"
        );
        assert!(
            asm.contains("STA ($FD),Y"),
            "READ A$(I) should store string pointer in array\n{asm}"
        );
        assert!(
            asm.contains(".byte $05,$41,$4C,$49,$43,$45"),
            "string DATA entry should be length-prefixed in DATA pool\n{asm}"
        );
    }

